import {
  Section,
  Link,
  Img,
  Body,
  Head as EmailHead,
  Html,
  Preview,
} from "jsx-email";
import { Fragment } from "react";
import type { CSSProperties, ReactNode } from "react";

import { DefaultFonts } from "@/components/email/font-default";
import { EmailTailwind } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type ButtonsVariant =
  | "primary"
  | "primary-leading-icon"
  | "primary-trailing-icon"
  | "secondary"
  | "secondary-leading-icon"
  | "secondary-trailing-icon"
  | "text"
  | "text-leading-icon"
  | "text-trailing-icon";

type ButtonSize = "xs" | "sm" | "md" | "lg" | "xl";

type EmailCssProperties = CSSProperties & {
  msoTextRaise?: string;
};
const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const msoRaise14: EmailCssProperties = { msoTextRaise: "14px" };

const msoRaise16: EmailCssProperties = { msoTextRaise: "16px" };

const sizes: Record<
  ButtonSize,
  {
    fontSize: number;
    iconWidth: number;
    lineHeight: number;
    paddingX: number;
    paddingY: number;
  }
> = {
  lg: {
    fontSize: 16,
    iconWidth: 14,
    lineHeight: 24,
    paddingX: 20,
    paddingY: 10,
  },
  md: {
    fontSize: 14,
    iconWidth: 14,
    lineHeight: 20,
    paddingX: 16,
    paddingY: 10,
  },
  sm: {
    fontSize: 14,
    iconWidth: 12,
    lineHeight: 20,
    paddingX: 12,
    paddingY: 8,
  },
  xl: {
    fontSize: 16,
    iconWidth: 16,
    lineHeight: 24,
    paddingX: 24,
    paddingY: 12,
  },
  xs: { fontSize: 12, iconWidth: 10, lineHeight: 16, paddingX: 8, paddingY: 4 },
};

const sizeOrder: ButtonSize[] = ["xs", "sm", "md", "lg", "xl"];

type ButtonAppearance = "primary" | "secondary" | "text";

type IconPosition = "leading" | "trailing";

const buttonsResponsiveStyles = `
  .emailcn-button-primary:hover { background-color: #4338ca !important; }
  .emailcn-button-secondary:hover { background-color: #f3f4f6 !important; }
`;

const getIconWidth = ({
  appearance,
  position,
  size,
  width,
}: {
  appearance: ButtonAppearance;
  position?: IconPosition;
  size: ButtonSize;
  width: number;
}) => {
  if (appearance === "primary" && position === "trailing") {
    return size === "xs" ? 10 : 12;
  }
  if (appearance !== "primary" && size === "xs") {
    return 11;
  }
  return width;
};

const getAppearanceStyles = (
  appearance: ButtonAppearance,
  withIcon: boolean
) => {
  if (appearance === "primary") {
    return {
      backgroundColor: "#4f46e5",
      buttonClass: "emailcn-button-primary",
      color: withIcon ? "#fffffe" : "#f8fafc",
    };
  }
  if (appearance === "secondary") {
    return {
      backgroundColor: withIcon ? "transparent" : "#fffffe",
      buttonClass: "emailcn-button-secondary",
      color: "#4b5563",
    };
  }
  return {
    backgroundColor: withIcon ? "transparent" : undefined,
    buttonClass: undefined,
    color: "#4f46e5",
  };
};

const getTextStyle = (position?: IconPosition): EmailCssProperties => {
  if (!position) {
    return msoRaise16;
  }
  return {
    ...msoRaise14,
    ...(position === "leading"
      ? { marginLeft: "8px" }
      : { marginRight: "8px" }),
  };
};

const Icon = ({
  appearance,
  customIcon,
  lineHeight,
  position,
  width,
}: {
  appearance: ButtonAppearance;
  customIcon?: ReactNode;
  lineHeight: number;
  position: IconPosition;
  width: number;
}) => {
  if (customIcon) {
    return <span>{customIcon}</span>;
  }
  const prefix = position === "leading" ? "icon-download" : "icon-arrow-right";
  let suffix = "-brand";
  if (appearance === "primary") {
    suffix = position === "leading" ? "-light" : "";
  } else if (appearance === "secondary") {
    suffix = "-dark";
  }
  return (
    <Img
      alt=""
      src={emailAsset(`${prefix}${suffix}.png`)}
      style={{
        lineHeight: `${lineHeight}px`,
        maxWidth: "100%",
        verticalAlign: "baseline",
      }}
      width={width}
    />
  );
};

const ButtonExample = ({
  align,
  appearance,
  customIcon,
  href,
  iconPosition,
  label,
  size,
}: {
  align: "center" | "left" | "right";
  appearance: ButtonAppearance;
  customIcon?: ReactNode;
  href: string;
  iconPosition?: IconPosition;
  label: string;
  size: ButtonSize;
}) => {
  const config = sizes[size];
  const isSecondary = appearance === "secondary";
  const isText = appearance === "text";
  const withIcon = iconPosition !== undefined;
  const iconWidth = getIconWidth({
    appearance,
    position: iconPosition,
    size,
    width: config.iconWidth,
  });
  const paddingY =
    appearance !== "primary" && size === "xs" ? 6 : config.paddingY;
  const { backgroundColor, buttonClass, color } = getAppearanceStyles(
    appearance,
    withIcon
  );
  const icon = iconPosition ? (
    <span style={msoRaise14}>
      <Icon
        appearance={appearance}
        customIcon={customIcon}
        lineHeight={config.lineHeight}
        position={iconPosition}
        width={iconWidth}
      />
    </span>
  ) : null;
  const text = <span style={getTextStyle(iconPosition)}>{label}</span>;
  return (
    <Section style={{ textAlign: align }}>
      <Link
        className={buttonClass}
        href={href}
        style={{
          backgroundColor,
          border: isSecondary ? "1px solid #d1d5db" : undefined,
          borderRadius: isText && !withIcon ? undefined : "8px",
          color,
          display: "inline-block",
          fontFamily,
          fontSize: `${config.fontSize}px`,
          fontWeight: isSecondary && !withIcon ? 600 : 500,
          lineHeight: `${config.lineHeight}px`,
          padding: `${paddingY}px ${config.paddingX}px`,
          textAlign: "center",
          textDecoration: "none",
        }}
      >
        {iconPosition === "leading" ? icon : null}
        {iconPosition === "leading" ? " " : null}
        {text}
        {iconPosition === "trailing" ? " " : null}
        {iconPosition === "trailing" ? icon : null}
      </Link>
    </Section>
  );
};

const ButtonsSection = ({
  align = "center",
  href = "https://example.com",
  icon,
  iconPosition,
  label,
  size = "all",
  variant = "primary",
}: {
  align?: "center" | "left" | "right";
  href?: string;
  icon?: ReactNode;
  iconPosition?: IconPosition;
  label?: string;
  size?: ButtonSize | "all";
  variant?: ButtonsVariant;
}) => {
  let appearance: ButtonAppearance = "primary";
  let resolvedIconPosition: IconPosition | undefined;
  if (variant.startsWith("secondary")) {
    appearance = "secondary";
  } else if (variant.startsWith("text")) {
    appearance = "text";
  }
  if (variant.includes("trailing")) {
    resolvedIconPosition = "trailing";
  } else if (variant.includes("leading")) {
    resolvedIconPosition = "leading";
  } else if (icon) {
    resolvedIconPosition = iconPosition ?? "leading";
  }
  let resolvedLabel = "Button";
  if (resolvedIconPosition === "trailing") {
    resolvedLabel = "Details";
  } else if (resolvedIconPosition === "leading") {
    resolvedLabel = "Download";
  }
  resolvedLabel = label ?? resolvedLabel;
  const visibleSizes = size === "all" ? sizeOrder : [size];
  return (
    <>
      <Section style={{ height: "100px" }} />
      <Section
        style={{
          backgroundColor: "#fffffe",
          fontSize: "16px",
          marginLeft: "auto",
          marginRight: "auto",
          maxWidth: "600px",
          textAlign: "start",
        }}
      >
        <Section
          style={{ paddingBottom: "44px", paddingTop: "44px", width: "100%" }}
        >
          {visibleSizes.map((buttonSize, index) => (
            <Fragment key={buttonSize}>
              <ButtonExample
                align={align}
                appearance={appearance}
                customIcon={icon}
                href={href}
                iconPosition={resolvedIconPosition}
                label={resolvedLabel}
                size={buttonSize}
              />
              {index < visibleSizes.length - 1 ? (
                <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
              ) : null}
            </Fragment>
          ))}
        </Section>
      </Section>
      <Section style={{ height: "100px" }} />
    </>
  );
};

interface Buttons_ButtonsProps {
  align?: "center" | "left" | "right";
  href?: string;
  icon?: ReactNode;
  iconPosition?: "leading" | "trailing";
  label?: string;
  size?: ButtonSize | "all";
  theme?: EmailTheme;
  variant?: ButtonsVariant;
}

const Buttons_Buttons = ({
  theme = defaultTheme,
  ...props
}: Buttons_ButtonsProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
      <style>{buttonsResponsiveStyles}</style>
    </EmailHead>
    <Preview>Buttons</Preview>
    <EmailTailwind theme={theme}>
      <Body className="m-0">
        <ButtonsSection {...props} />
      </Body>
    </EmailTailwind>
  </Html>
);

Buttons_Buttons.PreviewProps = {
  align: "center",
  href: "https://example.com",
  size: "all",
  theme: defaultTheme,
  variant: "primary",
} satisfies Buttons_ButtonsProps;

const __Buttons = Buttons_Buttons;

export interface ButtonProps {
  theme?: Parameters<typeof __Buttons>[0]["theme"];
  label?: string;
  href?: string;
  variant?: "primary" | "secondary" | "text";
  size?: "xs" | "sm" | "md" | "lg" | "xl" | "all";
  icon?: Parameters<typeof __Buttons>[0]["icon"];
  iconPosition?: "leading" | "trailing";
  align?: "left" | "center" | "right";
}

export const Button = ({
  theme,
  label,
  href,
  variant = "primary",
  size,
  icon,
  iconPosition = "leading",
  align,
}: ButtonProps) => (
  <__Buttons
    align={align}
    href={href}
    icon={icon}
    iconPosition={iconPosition}
    label={label}
    size={size}
    theme={theme}
    variant={
      icon
        ? (`${variant}-${iconPosition}-icon` as Parameters<
            typeof __Buttons
          >[0]["variant"])
        : variant
    }
  />
);

Button.PreviewProps = {
  iconPosition: "leading",
  variant: "primary",
} satisfies ButtonProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
